script:
frappe.ui.form.on('Medical Equipment', {
    before_save: function(frm) {
        // --- ส่วนที่ 1: บันทึก Calibration History ---
        if (frm.doc.last_calibration_date) {
            let cal_history = frm.doc.calibration_history_table || [];
            let last_cal_date = cal_history.length > 0 ? cal_history[cal_history.length - 1].calibration_date : null;

            if (frm.doc.last_calibration_date !== last_cal_date) {
                let row = frm.add_child('calibration_history_table');
                row.calibration_date = frm.doc.last_calibration_date;
                frm.refresh_field('calibration_history_table');
            }
        }

        // --- ส่วนที่ 2: บันทึก Maintenance History ---
        // ตรวจสอบว่ามีการกรอกข้อมูลทั้ง วันที่ และ ผู้ดูแล (maintenance_em) หรือไม่
        if (frm.doc.last_maintenance && frm.doc.maintenance_em) {
            let maint_history = frm.doc.maintenance_history_table || [];

            // ดึงค่าแถวล่าสุดมาเช็ก (เช็กทั้งวันที่และคนทำ เผื่อวันเดียวกันแต่เปลี่ยนคน)
            let last_maint = maint_history.length > 0 ? maint_history[maint_history.length - 1] : null;

            if (!last_maint || 
                frm.doc.last_maintenance !== last_maint.date_maintenance || 
                frm.doc.maintenance_em !== last_maint.maintenance_em) {

                // เพิ่มแถวใหม่ใน Maintenance History Table
                let row = frm.add_child('maintenance_history_table');
                row.date_maintenance = frm.doc.last_maintenance; // นำค่า last_maintenance ไปที่ช่อง date_maintenance
                row.maintenance_em = frm.doc.maintenance_em;    // นำค่า maintenance_em ไปที่ช่อง maintenance_em

                frm.refresh_field('maintenance_history_table');
                console.log("New maintenance history added.");
            }
        }
    }
});


frappe.ui.form.on('Medical Equipment', {
    refresh: function(frm) {
        render_risk_indicator(frm);
    },
    list: function(frm) {
        render_risk_indicator(frm);
    },
    risk_type: function(frm) {
        render_risk_indicator(frm);
    }
});

function render_risk_indicator(frm) {
    // --- ส่วนที่ปรับขนาดได้ตรงนี้ครับ ---
    const dot_size = "20px";   // ขนาดเส้นผ่าศูนย์กลางของจุด (เช่น 12px, 16px, 20px)
    const font_size = "20px";  // ขนาดตัวอักษรของชื่ออุปกรณ์ (เช่น 14px, 16px, 22px)
    const gap_size = "12px";   // ระยะห่างระหว่างจุดกับตัวอักษร
    // -------------------------------

    let equipment_name = frm.doc.list || "";
    let risk = frm.doc.risk_type;
    let color = "black"; 

    // กำหนดสีตามระดับความเสี่ยง
    if (risk === "ความเสี่ยงต่ำ") {
        color = "#28a745"; // สีเขียว
    } else if (risk === "ความเสี่ยงปานกลาง") {
        color = "#ffc107"; // สีเหลือง
    } else if (risk === "ความเสี่ยงสูง") {
        color = "#dc3545"; // สีแดง
    }

    if (equipment_name) {
        let html_content = `
            <div style="display: flex; align-items: center; gap: ${gap_size}; padding: 10px 0;">
                <div style="
                    width: ${dot_size}; 
                    height: ${dot_size}; 
                    background-color: ${color}; 
                    border-radius: 50%;
                    flex-shrink: 0;
                    display: inline-block;
                "></div>

                <span style="
                    font-size: ${font_size}; 
                    font-weight: 600; 
                    color: #1f2d3d;
                    line-height: 1;
                ">
                    ${equipment_name}
                </span>
            </div>
        `;

        // อย่าลืมเปลี่ยน 'display_html' ให้ตรงกับชื่อ Field HTML ของคุณ Jinda นะครับ
        if (frm.fields_dict.display_html) {
            frm.fields_dict.display_html.$wrapper.html(html_content);
        }
    } else {
        if (frm.fields_dict.display_html) {
            frm.fields_dict.display_html.$wrapper.html("");
        }
    }
}

frappe.listview_settings['Medical Equipment'] = {
    refresh: function(listview) {
        // เพิ่มปุ่ม "แจ้งเตือน PM" ไว้ที่แถบเครื่องมือด้านบนหน้า List
        listview.page.add_inner_button(__('📢 แจ้งเตือน PM'), function() {
            check_pm_logic(listview);
        });
    }
};

function check_pm_logic(listview) {
    const now = new Date();
    const current_day = now.getDate();
    const current_month_index = now.getMonth(); // 0 = มกราคม

    const month_names = [
        "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
        "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
    ];

    let target_month = "";
    let alert_title = "";

    // --- Logic ตรวจสอบช่วงวันที่ 15 ถึงวันที่ 1 ---
    if (current_day >= 15) {
        const next_month_index = (current_month_index + 1) % 12;
        target_month = month_names[next_month_index];
        alert_title = `แผน PM ล่วงหน้าสำหรับเดือน ${target_month}`;
    } 
    else if (current_day === 1) {
        target_month = month_names[current_month_index];
        alert_title = `แผน PM ประจำเดือน ${target_month}`;
    }
    else {
        frappe.prompt([
            {
                label: 'เลือกเดือนที่ต้องการดูแผน PM',
                fieldname: 'month',
                fieldtype: 'Select',
                options: month_names,
                default: month_names[current_month_index]
            }
        ], (values) => {
            fetch_and_show_pm(values.month, `แผน PM เดือน ${values.month}`);
        }, __('ระบุเดือนที่ต้องการเช็ค'), __('ตกลง'));
        return;
    }

    if (target_month) {
        fetch_and_show_pm(target_month, alert_title);
    }
}

function fetch_and_show_pm(month, title) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Medical Equipment',
            filters: { 'pm_plan': month },
            fields: ['name', 'list', 'quipment_code'], 
            limit: 500
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                let items_html = r.message.map(item => {
                    let url = frappe.utils.get_form_link('Medical Equipment', item.name);

                    return `
                    <div style="padding: 12px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center;">
                        <span>
                            <a href="${url}" style="font-weight: bold; color: #171717; text-decoration: none; font-size: 14px;">
                                ${item.quipment_code || item.name}
                            </a> 
                            <span style="margin-left: 10px; color: #444;">${item.list || ''}</span>
                        </span>
                        <button class="btn btn-xs btn-primary" 
                                style="padding: 5px 12px; font-size: 11px; border-radius: 4px; background-color: #007bff; color: white; border: none;">
                            ติดต่อ PM
                        </button>
                    </div>`;
                }).join('');

                frappe.msgprint({
                    title: `<b style="color: #007bff;">${title}</b>`,
                    message: `<div id="pm-list-container" style="max-height: 450px; overflow-y: auto;">${items_html}</div>`,
                    wide: true
                });

            } else {
                frappe.msgprint({
                    title: `<b>${title}</b>`,
                    indicator: 'orange',
                    message: `ไม่พบรายการเครื่องมือแพทย์ที่อยู่ในแผน PM เดือน ${month}`
                });
            }
        }
    });
}
